#include <iostream>
#include <cstring>
#include <vector>
#include <string>
#include <functional>
#include <unordered_map>
#include <memory>
#include <algorithm>

namespace ws {

static constexpr size_t MAX_FRAME_SIZE = 65536;
static constexpr size_t AUTH_TOKEN_MAX = 256;
static constexpr size_t HEADER_POOL_SIZE = 512;

struct AuthContext {
    char service_id[64];
    char token[AUTH_TOKEN_MAX];
    uint32_t permissions;
    bool validated;
};

struct FrameHeader {
    uint8_t opcode;
    uint8_t mask_bit;
    uint64_t payload_length;
    uint8_t masking_key[4];
};

class HeaderPool {
public:
    HeaderPool() : pool_(HEADER_POOL_SIZE), write_pos_(0) {}

    char* allocate(size_t len) {
        if (write_pos_ + len > pool_.size()) {
            write_pos_ = 0; // wrap around - ring buffer semantics
        }
        char* ptr = &pool_[write_pos_];
        write_pos_ += len;
        return ptr;
    }

    void reset() { write_pos_ = 0; }

private:
    std::vector<char> pool_;
    size_t write_pos_;
};

class CrossServiceAuth {
public:
    bool validate_token(const char* token, size_t token_len, AuthContext& ctx) {
        if (token_len == 0 || token_len > AUTH_TOKEN_MAX) return false;

        // Parse service_id from token format: "service_id:hmac_signature"
        const char* delimiter = static_cast<const char*>(memchr(token, ':', token_len));
        if (!delimiter) return false;

        size_t id_len = delimiter - token;
        if (id_len >= sizeof(ctx.service_id)) return false;

        memcpy(ctx.service_id, token, id_len);
        ctx.service_id[id_len] = '\0';
        memcpy(ctx.token, token, token_len);
        ctx.token[token_len] = '\0';

        // Lookup permissions for this service
        ctx.permissions = lookup_permissions(ctx.service_id);
        ctx.validated = (ctx.permissions != 0);
        return ctx.validated;
    }

private:
    uint32_t lookup_permissions(const char* service_id) {
        // Simulated permission lookup
        if (strcmp(service_id, "gateway") == 0) return 0xFF;
        if (strcmp(service_id, "worker") == 0) return 0x0F;
        if (strcmp(service_id, "monitor") == 0) return 0x01;
        return 0;
    }
};

class WebSocketConnection {
public:
    WebSocketConnection() : authenticated_(false), header_pool_() {}

    bool process_frame(const uint8_t* data, size_t length) {
        if (length < 2) return false;

        FrameHeader header;
        size_t offset = parse_frame_header(data, length, header);
        if (offset == 0) return false;

        if (header.payload_length > MAX_FRAME_SIZE) return false;

        const uint8_t* payload = data + offset;
        size_t payload_available = length - offset;

        if (payload_available < header.payload_length) return false;

        // Unmask payload
        std::vector<uint8_t> unmasked(header.payload_length);
        if (header.mask_bit) {
            for (size_t i = 0; i < header.payload_length; i++) {
                unmasked[i] = payload[i] ^ header.masking_key[i % 4];
            }
        } else {
            memcpy(unmasked.data(), payload, header.payload_length);
        }

        return dispatch_message(header.opcode, unmasked.data(), unmasked.size());
    }

private:
    size_t parse_frame_header(const uint8_t* data, size_t len, FrameHeader& hdr) {
        if (len < 2) return 0;

        hdr.opcode = data[0] & 0x0F;
        hdr.mask_bit = (data[1] >> 7) & 0x01;
        uint8_t len_field = data[1] & 0x7F;

        size_t offset = 2;

        if (len_field <= 125) {
            hdr.payload_length = len_field;
        } else if (len_field == 126) {
            if (len < 4) return 0;
            hdr.payload_length = (static_cast<uint16_t>(data[2]) << 8) | data[3];
            offset = 4;
        } else {
            if (len < 10) return 0;
            hdr.payload_length = 0;
            for (int i = 0; i < 8; i++) {
                hdr.payload_length = (hdr.payload_length << 8) | data[2 + i];
            }
            offset = 10;
        }

        if (hdr.mask_bit) {
            if (len < offset + 4) return 0;
            memcpy(hdr.masking_key, data + offset, 4);
            offset += 4;
        }

        return offset;
    }

    bool dispatch_message(uint8_t opcode, const uint8_t* payload, size_t len) {
        switch (opcode) {
            case 0x01: // Text frame - auth messages
                return handle_auth(payload, len);
            case 0x02: // Binary frame - data messages
                return handle_data(payload, len);
            case 0x09: // Ping
                return handle_ping(payload, len);
            default:
                return false;
        }
    }

    bool handle_auth(const uint8_t* payload, size_t len) {
        // Auth message format: "AUTH <token>"
        if (len < 5) return false;
        if (memcmp(payload, "AUTH ", 5) != 0) return false;

        const char* token = reinterpret_cast<const char*>(payload + 5);
        size_t token_len = len - 5;

        CrossServiceAuth auth;
        authenticated_ = auth.validate_token(token, token_len, auth_ctx_);
        return authenticated_;
    }

    bool handle_data(const uint8_t* payload, size_t len) {
        if (!authenticated_) return false;
        if (!(auth_ctx_.permissions & 0x02)) return false; // need write permission

        return process_data_payload(payload, len);
    }

    bool process_data_payload(const uint8_t* payload, size_t len) {
        // Data format: [2-byte header_count][headers...][body]
        if (len < 2) return false;

        uint16_t header_count = (static_cast<uint16_t>(payload[0]) << 8) | payload[1];
        size_t pos = 2;

        // Process each header: [2-byte key_len][key][2-byte val_len][value]
        for (uint16_t i = 0; i < header_count; i++) {
            if (pos + 2 > len) return false;
            uint16_t key_len = (static_cast<uint16_t>(payload[pos]) << 8) | payload[pos + 1];
            pos += 2;

            if (pos + key_len > len) return false;
            const char* key = reinterpret_cast<const char*>(payload + pos);
            pos += key_len;

            if (pos + 2 > len) return false;
            uint16_t val_len = (static_cast<uint16_t>(payload[pos]) << 8) | payload[pos + 1];
            pos += 2;

            if (pos + val_len > len) return false;
            const char* val = reinterpret_cast<const char*>(payload + pos);
            pos += val_len;

            // Store header in pool for later processing
            // key_len + val_len + 2 null terminators + 4 bytes for lengths
            size_t total_entry = key_len + val_len + 6;
            char* entry = header_pool_.allocate(total_entry);

            // Write key_len, key, val_len, val into entry
            uint16_t kl_net = key_len;
            uint16_t vl_net = val_len;
            memcpy(entry, &kl_net, 2);
            memcpy(entry + 2, key, key_len);
            entry[2 + key_len] = '\0';
            memcpy(entry + 3 + key_len, &vl_net, 2);
            memcpy(entry + 5 + key_len, val, val_len);
            entry[5 + key_len + val_len] = '\0';
        }

        return true;
    }

    bool handle_ping(const uint8_t* payload, size_t len) {
        // Echo back as pong - max 125 bytes per RFC 6455
        char pong_buf[125];
        size_t copy_len = std::min(len, sizeof(pong_buf));
        memcpy(pong_buf, payload, copy_len);
        // Would send pong_buf back
        return true;
    }

    bool authenticated_;
    AuthContext auth_ctx_;
    HeaderPool header_pool_;
};

} // namespace ws

int main() {
    ws::WebSocketConnection conn;

    // Simulate receiving auth frame
    std::string auth_msg = "AUTH gateway:valid_hmac_sig_here";
    std::vector<uint8_t> frame;
    frame.push_back(0x81); // FIN + text opcode
    frame.push_back(static_cast<uint8_t>(auth_msg.size())); // no mask, len < 126
    frame.insert(frame.end(), auth_msg.begin(), auth_msg.end());

    conn.process_frame(frame.data(), frame.size());

    std::cout << "WebSocket server running..." << std::endl;
    return 0;
}
